import java.util.*;
public class Question_13{static void dfs(String v,Map<String,List<String>>g,Set<String>s){if(!s.add(v))return;for(String w:g.get(v))dfs(w,g,s);}public static void main(String[]x){Map<String,List<String>>g=new LinkedHashMap<>();g.put("CHN",List.of("BLR","HYD"));g.put("BLR",List.of("CBE","MYS"));g.put("HYD",List.of("PUN"));g.put("CBE",List.of("MUM"));g.put("MYS",List.of("CBE"));g.put("PUN",List.of("DEL"));g.put("MUM",List.of());g.put("DEL",List.of());g.put("KOL",List.of("DEL"));g.put("JAI",List.of("PUN"));Queue<String>q=new ArrayDeque<>();Map<String,String>p=new HashMap<>();q.add("CHN");p.put("CHN",null);while(!q.isEmpty()){String v=q.remove();for(String w:g.get(v))if(!p.containsKey(w)){p.put(w,v);q.add(w);}}List<String>path=new ArrayList<>();if(p.containsKey("MUM")){for(String v="MUM";v!=null;v=p.get(v))path.add(v);Collections.reverse(path);}Set<String>seen=new LinkedHashSet<>();dfs("CHN",g,seen);System.out.println("Fewest-hop route: "+path);System.out.println("Reachable from CHN: "+seen);}}